import{_ as t,C as o,o as r,c as l,j as e,a as i,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"关于金钱的真相(以及如何赚到一大笔钱)","description":"","frontmatter":{"title":"关于金钱的真相(以及如何赚到一大笔钱)","originalTitle":"The Truth About Money (And How To Make A Ton Of It)","date":"2024-09-21","originalUrl":"https://thedankoe.com/letters/the-truth-about-money-and-how-to-make-a-ton-of-it/","minutes":20,"sourceHash":"ccad0db49658ddde83f5fe3273056adef578c88980363ddb7e39f207a39f9c74","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-truth-about-money-and-how-to-make-a-ton-of-it/"}]]},"headers":[],"relativePath":"letters/the-truth-about-money-and-how-to-make-a-ton-of-it.md","filePath":"letters/the-truth-about-money-and-how-to-make-a-ton-of-it.md"}'),s={name:"letters/the-truth-about-money-and-how-to-make-a-ton-of-it.md"};function u(d,p,c,m,b,f){const a=o("ArticleMeta");return r(),l("div",null,[p[0]||(p[0]=e("h1",{id:"关于金钱的真相-以及如何赚到一大笔钱",tabindex:"-1"},[i("关于金钱的真相(以及如何赚到一大笔钱) "),e("a",{class:"header-anchor",href:"#关于金钱的真相-以及如何赚到一大笔钱","aria-label":'Permalink to "关于金钱的真相(以及如何赚到一大笔钱)"'},"​")],-1)),n(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/j4ltbwDegHg?si=ZABIe1NeYLeiv-98" target="_blank" rel="noreferrer">观看原文视频</a></p><p>大多数人都在金钱问题上苦苦挣扎。</p><p>这是事实。</p><p>金钱与现代人的生存深深交织在一起。</p><p>它影响着你生活的每一个领域。即使你没在想钱,你其实也在想钱。你的健康取决于你的钱。你人际关系的健全程度,也取决于一个基本的资金水平。</p><p>你可以说这不公平,抱怨事情本该不是这样,但我强烈不同意。</p><p>我不是来告诉你,关于金钱的真相被某种方式&quot;隐藏&quot;起来了。</p><p>你陷入这种境地,是你自己的错。</p><p>你从未质疑过自己被养育的方式,养成了一种糟糕的金钱心理关系,正因为如此,你没能明白赚钱本身就是一种技能。你可以赚到你想要的任何数额,只是你没有花时间去研究、练习、精通这项技能。</p><p>我写这封信的目的,是在你脑中植入正确的金钱程序,因为这是赚到你想要的钱的第一步。</p><p>以下是我们将要探讨的内容:</p><ul><li>为什么金钱问题并不存在,存在的是心理问题(以及如何消除你的稀缺心态)。</li><li>工作、职业和使命之间的区别,这样你才能靠做自己想做的事赚取收入。</li><li>一种关于金钱的新视角,以及它如何是通往充实人生的钥匙(而不是阻碍充实人生的东西)。</li><li>在任何经济形势下如何赚钱的完整拆解,因为赚钱本身就是一种技能。</li></ul><p>面对现实吧。</p><p>你想要自由。</p><p>好吧,或许不是完全的自由……我们人类喜欢结构和限制(否则我们早就自由了,因为自由是一种心理状态)。</p><p>至少,你想要的是自主权。</p><p>选择自己限制的能力。</p><p>读完这封信,你就会拥有这一点。</p><hr><p>温和提醒:</p><p>我们正在推出Kortex的使用权限。</p><p>Kortex是为作家、创作者和笔记记录者打造的第二大脑。</p><p>你可以捕捉任何想法、保存任何高亮或书签、创建原子笔记,并在一个互联的数据库中,在一个视图里引用任何想法。</p><p>如果你已经厌倦了把想法保存在各种随机的应用里,然后失去了所有最好的点子:</p><p><a href="https://kortex.co/" target="_blank" rel="noreferrer">&gt;&gt; 在这里加入Kortex等候名单。</a></p><hr><h2 id="普通人的金钱心态" tabindex="-1">普通人的金钱心态 <a class="header-anchor" href="#普通人的金钱心态" aria-label="Permalink to &quot;普通人的金钱心态&quot;">​</a></h2><p>金钱问题并不存在。存在的是心理问题。</p><p>大多数人无法赚钱、留住钱、或聪明地使用钱,归根结底是他们的信念问题,因为你的信念决定了你能注意到哪些机会去做这些事。</p><p>以下是普通人关于金钱的一系列信念:</p><ul><li>你相信钱很难赚。</li><li>你不相信金钱像健康、人际关系或你的工作一样,是一个可以精通的领域。</li><li>你可能相信金钱是邪恶的(因为之前的负面经历给你植入了这种程序)。</li><li>你对创业不感兴趣,因为你只看到了油腔滑调的推销员和漫长工时这种表面现象。</li><li>你觉得每个人都在试图骗你,或者认为任何非巨型公司都是骗子(而事实上,它们通常就是你说自己支持的那些独立企业)。</li><li>你被困在生存模式里,所以你看不到自我发展或商业的重要性,并感到有种冲动想把它们一笔抹杀,以让自己对自己的行为感觉好一点。</li><li>你认为自己在自己的领域里赚不到大钱,这纯粹是错的——你只要观察一下你所在领域里赚钱最多的人就知道了(提示:他们都有自己的生意)。</li></ul><p>以上每一条,都在限制你能赚到的钱。</p><p>如果你相信赚钱不是一种技能,你就不会去学习这项技能。</p><p>如果你相信金钱是邪恶的,你就会对赚更多钱的想法感到排斥(即便这是你摆脱自己造成的混乱局面的唯一出路)。</p><p>你对金钱的认知,由你的发展阶段决定。</p><p>我有一个自己的概念,叫做<strong>目的的层级(Levels Of Purpose)。</strong></p><p>解决你金钱问题(心理问题)的方法,就是逐层向上推进。</p><p>金钱的目的会随着你自身的发展而改变。它一开始是生存的手段,然后变成获取地位的方法,进而引发对自主权的渴望,接着变成创造力和自我表达的燃料,最后转化为一种帮助他人经历类似阶段的方式——无论是否与金钱相关。</p><p>这些就是各个层级:生存、地位、自主、创造,和贡献。</p><h3 id="生存" tabindex="-1">生存 <a class="header-anchor" href="#生存" aria-label="Permalink to &quot;生存&quot;">​</a></h3><p>我们上面列出的每一条信念,追求的目标和目的都是生存。</p><p>你的主要目的决定了你如何感知各种情境。在生存阶段,你不会注意到赚钱的机会,因为你的注意力全部被房子、房贷、工作带来的疲惫、由此衍生出来的关系问题所占据,你甚至几乎没有余钱可以让你静下心来思考。</p><p>你会接受任何能找到的工作,因为你必须生存。而在你生命中的这个阶段,当你的目标是你所受教养的产物时,你没有多少可以让自己享受的工作选项。</p><p>你要逃离生存阶段,方法是深刻意识到你的信念是如何阻碍你的——它们如何在你的生活中制造出一连串毁灭性的连锁反应。</p><p>然后,你把注意力转向解决那些浮现出来的问题,而在这个阶段,那几乎总是仅仅是&quot;赚更多钱&quot;。这没什么不好。我甚至会说这是必要的。你之所以停留在这个阶段,是因为你忽视了——甚至可能鄙视——对它的需求。</p><h3 id="地位" tabindex="-1">地位 <a class="header-anchor" href="#地位" aria-label="Permalink to &quot;地位&quot;">​</a></h3><p>正如我们最近所讨论的,历史上从来没有哪个时期,弱者、平庸之人或思维麻木的人不被当作牲畜对待。令人愤怒的是,在社会上过得好的人,往往只是那些获得了权力和影响力的人。</p><p>当你(1)对金钱有一定的安全感,且(2)意识到需要让他人认为你有价值时,你就到达了地位阶段。</p><p>你培养出一套技能,让你能找到更好的工作,或开创一份事业。这份工作让你能支付账单,专注于生活的其他领域,并实现从适度到奢华的表面性目标。</p><p>许多不擅长批判性思考的人认为这是坏事,但他们不懂感知或心理学。人类必须先注意到表面,才能注意到深度。我不管你的&quot;性格有多好&quot;。人们在决定与某人建立关系之前,确实会在意外表。</p><h3 id="创造" tabindex="-1">创造 <a class="header-anchor" href="#创造" aria-label="Permalink to &quot;创造&quot;">​</a></h3><p>一旦你达到了某种地位,你的心智就会开始转变。</p><p>你会开始意识到自己所有的错误。</p><p>那些错误,是需要去解决的新问题。是需要去追求的新目的。</p><p>你甚至可能会感到有一种冲动,想要抛弃你所获得的一切。</p><p>你不会再从那些表面性的追求中找到过去那样的快乐了。</p><p>钱变得乏味了。滥交变得乏味了。车和手表也变得乏味了。</p><p>这并不意味着你之前所做的一切都是白费。你拥有一大缸经验,可以从中汲取,并传递给他人。</p><p>你会开始渴望自主权。你会意识到,当你在地位游戏中越往上爬,进展就变得越缓慢,你也会想要接受更难的挑战。</p><p>到了这个阶段,你的重心必须转向,在少数几个追求上培养一种哲学层面的精通感。</p><p>对健身爱好者来说,去健身房一开始是为了让自己感觉良好而追求的目标。几年之后,他们要么放弃,要么转向一个更深、更有意义的新目标,让这段旅程更有意义。他们从健康食物中找到快乐。他们对自己的健康选择如何影响未来有了深刻的理解。他们从在健身房里一点一滴的进步过程中获得成就感。</p><p>这就是创造阶段。</p><p>在地位阶段,你学到和做的大部分事情,都来自别人教你的东西,来自你从他人那里吸收学到的内容。</p><p>到了创造阶段,你会带着扩展后的知识,开始创造出属于自己的做事方式。</p><p>你尝试过不同的训练方案、商业模式和应对策略,直到你意识到它们之间存在的模式和原则。你已经解锁了一种心智层级,能够优雅地在它们之间游走自如。</p><p>在创造阶段,你的任务就是单纯地去创造。</p><p>打破你从别人那里吸纳来的教条、意识形态和流程。从零开始构建新颓的解决方案。(译注:此处应为&quot;新颖的解决方案&quot;)这会为你顺利进入贡献阶段打下良好基础。</p><h3 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h3><p>凭借高价值技能与足够多的创造性实验相结合,你意识到自己可以深刻影响他人的生活,并感受到一种想要这样做的召唤。</p><p>你产生了一种深切的渴望,想要&quot;分享&quot;那些改善了你生活的东西。</p><p>你开始从一个新的视角看待生活,并开始好奇为什么别人总是被琢碎小事分散注意力。(译注:琐碎)你能看清他们的人生走向何处,但他们自己却看不清。</p><p>贡献阶段,是你生活中曾经彼此分离的各个领域,如今坍缩为一体的阶段。</p><p>你不再把工作看作是一个打卡上班、打卡下班的地方。</p><p>你不再把休息看作是只有在工作完成后才能享受的奖赏。</p><p>你不再把玩乐看作是一种爱好,只有在晚上有空闲的30分钟里才能沉浸其中。</p><p>你把它们全都视为彼此必要的平衡对立面。</p><p>工作、休息与玩乐,变得难以区分。</p><p>休息成为了为你的工作重新激发创造力的方式。玩乐成为了你工作的方式。工作与你的生活深度融合,以至于你所做的任何事,都可以以产品或信息的形式传递下去。</p><p>你的整个生活,开始围绕着&quot;我能如何最好地为世界做出贡献&quot;这个问题运转。</p><p>你成为了现实的一种视角载体。你用自己的心智去理解这个世界,并把这种视角传递下去,供他人采纳并从中受益。</p><p>你去搜寻并收集信息,将其与你的经验相融合,再分发给那些想从中受益的人。</p><p>你不再像个寄生虫。你不再只是从现实中索取、为一己私利消耗资源,而是开始创造、分享,并向这个世界回馈贡献。</p><p>关于这些层级,最后再补充几点:</p><p>当你开始创业时,这些层级会重置。当你辞职去创业时,你又回到了生存模式。你需要地位来获取正确的人脈和资源。你开始渴望摆脱像客户工作和可以委托的任务这类事情所带来的束缚,获得自主权。你腾出心力去进行创造。最终,你会意识到,你的核心目的是帮助他人。</p><p>这些目的的层级遵循&quot;超越并包含&quot;的法则。你永远不会&quot;逃离&quot;生存阶段,你只是把它整合进来。你利用它,把它当作杠杆。</p><h2 id="生活的艺术-就是靠玩乐赚钱" tabindex="-1">生活的艺术,就是靠玩乐赚钱 <a class="header-anchor" href="#生活的艺术-就是靠玩乐赚钱" aria-label="Permalink to &quot;生活的艺术,就是靠玩乐赚钱&quot;">​</a></h2><blockquote><p>有头脑的人,靠做自己喜欢的事赚钱。——艾伦·瓦茨(Alan Watts)</p></blockquote><p>我们从出生起就被训练成为每个人工作,除了自己。</p><p>我们被分配任务,走上早已被踩踏过的路径。</p><p>我们不带任何挣扎或有意识的思考去完成这些任务,最终在一个充斥着这样一群人的社会中,沦为一个机械化、可被替换的角色——这些人拼命向外证明自己的幸福,以掩藏自己内心的痛苦。</p><p>我们不知道还有更好的方式,因为我们所知道的,不过是别人告诉我们的东西。</p><p>我们被教导去读自己不关心的书，去完成自己不关心的项目，以此为一种自己并不关心的生活做准备。在你意识到之前，你已经被困在了一片浓密的责任之云中。那些原本可以用来改变你人生的资源——时间、精力和金钱——像时钟一样被规律地耗尽，于是你别无选择，只能继续做一个高效运转的机器人，正如社会为你安排的那样。</p><p><em>如果你厌恶自己的工作，而它占据了你生命的三分之一；它又榨干了你的精力，让你无法享受另外三分之一的时间；而剩下的三分之一你都在睡觉——那么，似乎没有什么事情比创造、建造、设计、写作、销售、投资、拥有、实验、并发现一种能掌控自己每一天的方式更为重要了。</em></p><p><strong>在你追寻有目的的财富之路上，你会发现——工作（job）、事业（career）与天命（calling）之间的区别。</strong></p><p>工作（job）是你为别人做的一件令人不快的事，唯一的目的就是赚钱。</p><p>工作是一种生存机制。</p><p>工作是通往满足那些塑造了你心智的人的期望之路上的一个里程碑。</p><p>从某种角度看，工作和学校很相似——好的营销可以掩盖糟糕的产品。</p><p>经过几个世纪的失败，它们依然存活并且兴盛,原因很简单——很少有人愿意费心去独立思考。大多数人只是在做大多数人都做的事。大多数人并不满意大多数人得到的结果，但到了那个时候，逃脱已经变得更加困难。</p><p>事业（career）是一种对自身工作中的成长的承诺。</p><p>事业要求你去追求一系列具有挑战性的角色和任务的阶梯。</p><p>从心理层面上讲，这为你的心智带来了长期的秩序与清晰。</p><p>每一次挑战的升级，都会让生活变得更加复杂而有趣。新的知识和技能获取路径也随之显现。如果你想在事业上更进一步，在某种程度上，你必须先把自己的生活理顺。</p><p>天命（calling）是一种你无法把自己从中抽离的工作，别人也无法不为之付钱给你。</p><p>天命是无法被指派给你的。</p><p>天命无法在他人的命令下被追寻。</p><p>天命无法被限定在固定的工作时长内，因为你的心智一直在为它运转。</p><p>天命出现在改进演变为执念的那一刻。</p><p>天命是别人无法理解的东西。它必须被那个追寻它的人所珍视、保护和维护，就像一份可能被别人不小心偷走的礼物。</p><p>工作不是事业，也不是天命，但事业和天命都是工作。事业不是天命，但天命是一种事业。</p><p>工作非常适合那些还不知道自己想要什么，或仅仅需要生存的年轻人。</p><p>事业非常适合那些想要在生活中获得更多满足感的人，因为他们明白，具有挑战性的工作是自我发展的一种推动力。</p><p>天命是为那些知道自己注定要成就更多的人而存在的。</p><p>是那少数愿意跳入未知，并对自己人生结果全权负责的人。</p><p>一个令人悲哀的事实是，如今“工作”这个词已被视为一种诅咒。当普通人想到工作时，他们的脑海中就会涌现出熟悉的过去和可预见的未来——压力、疲惫和焦虑。</p><p>当你在工作时，你渴望休息；当你在休息时，你最终又渴望工作。这是一个永远感觉不到自己身处所想之地的灾难性循环。</p><p>你的心思总在别处，从不在当下。</p><p>人们梦想着我们称之为退休的永恒假期，但一旦他们实现了这种幻想，它也会像其他一切一样变得平常。</p><p>几周之内，你就会忍不住想在“存在”与“行动”之间找到平衡。</p><p>你应该把创造一种像玩耍一样的工作，当作自己的全职事业。</p><p>要摆脱那种“工作是坏的、金钱是邪恶的”的狭隘观念。</p><p>如果你困在一份工作中，或正接近事业阶梯的顶端，有一件事可以把你推向下一个阶段：</p><p>意识到金钱远比你想象的更具精神性。</p><h2 id="金钱远比你想象的更具精神性" tabindex="-1">金钱远比你想象的更具精神性 <a class="header-anchor" href="#金钱远比你想象的更具精神性" aria-label="Permalink to &quot;金钱远比你想象的更具精神性&quot;">​</a></h2><p>我们工作、工作、再工作，直到赚够了钱去休息，结果却发现自己对拥有的一切以及自己的渺小都感到不满。</p><p>我们淹没在生存模式之中。</p><p>我们从未成功看穿那些被分配给我们、又被我们不加质疑地接受的责任之外的东西。</p><p>醒来，去上班，应付老板，因为没时间就吃方便食品，因为没精力就放弃了自己曾承诺要坚持的好习惯,眼看着自己的生活因心智、身体和关系的逐渐瓦解而慢慢崩溃,却无所作为，因为这是你唯一了解的生活。</p><p>要意识到，工作是生活中不可或缺的一部分。</p><p>工作的本质是解决问题。</p><p>人类热爱解决问题，但不是任何问题都行，而是我们认为有意义且有趣的问题。</p><p>正确的问题会收窄我们的注意力，让我们忘却烦恼。</p><p>错误的问题会奴役我们的注意力，放大我们的烦恼。</p><p>二者的区别在于——一个是自己选择的,另一个是被分配的。问题是限制你心智与潜力的边界。一旦被解决，它们便为成长、扩展与进化打开了空间。</p><p>金钱本身是一项美妙的发明。</p><p>它让我们能够通过价值交换来超越单纯的生存。</p><p>我们每个人都有自己觉得值得去解决的问题。于是我们解决了它，很快便产生了帮助别人也解决同样问题的渴望。但由于有些人没有时间、技能或意愿，金钱这项发明便让他们能用一种不同的资源来解决问题（或者至少让解决问题变得容易得多）。</p><p>所以，如果问题是限制你潜力的边界……是那些阻止你到达人生下一个目标层次的东西，那么金钱就是实现你潜力的一种工具。</p><p>而如今，没有问题，也就没有目的（purpose）可言。</p><p>通过解决一个问题，你便在追寻一种目的。你发现了自己在某个更宏大事物中的角色。这就是所谓的“精神性”——发现自己在整体中的位置，超越那个整体，进入下一个,再进入下一个,直至到达你人生中“贡献”这一终极目的。</p><p>大多数身处商业中的人都被困在“生存”与“地位”这两个阶段。</p><p>这就是为什么你会觉得他们缺乏精神性。</p><p>但商业不过是一种用来分配价值的合法结构。并非所有企业都是邪恶的，但如果你不去创办自己的企业,那些邪恶的企业就必然会兴盛。</p><p>当你还处于生存或地位阶段时，如果不去创办自己的企业，你就必然会在不知不觉中,因为为某个荼毒大众的公司工作，而助长了你所认为邪恶的那些企业。</p><p>总结一下——如果你人生的目的是为人类作出贡献，那么追寻你的天命（而不是把工作或事业当作终点）就是其中的一部分。而你的天命,几乎总是要通过你自己的企业去实现。</p><h2 id="赚钱是一种技能-不是运气" tabindex="-1">赚钱是一种技能，不是运气 <a class="header-anchor" href="#赚钱是一种技能-不是运气" aria-label="Permalink to &quot;赚钱是一种技能，不是运气&quot;">​</a></h2><p>赚钱与运气无关。</p><p>我们早已超越了那种幼稚的信念。</p><p>我们不再生活在那样的世界里了。</p><p>“运气”这个概念，只是用来描述我们对一个系统缺乏理解的说法。</p><p>如果你理解了赚钱的系统，你就可以随心所欲地赚钱（当然前提是你真正学会了相关技能）。</p><p>以下正是你需要理解的内容，才能赚到你想要的任何数量的钱。</p><h3 id="_1-理解-一个人-的心理-最好是理解你自己的。" tabindex="-1">1）理解“一个人”的心理，最好是理解你自己的。 <a class="header-anchor" href="#_1-理解-一个人-的心理-最好是理解你自己的。" aria-label="Permalink to &quot;1）理解“一个人”的心理，最好是理解你自己的。&quot;">​</a></h3><p>钱从哪里来？</p><p>我说的不是政府怎么印钱。</p><p>我说的是——<em>它是怎么落到你手里的？</em></p><p>是有人把它给了你。</p><p>这就是答案。</p><p>无论它来自一个消费者还是一家企业，总有人做出决定,把钱交到你手上，因为他们<em>认为你所提供的东西是有价值的。</em></p><p>创造出值得付费的东西的第一步，是理解“一个人”的心理。价值即是感知。</p><p>甲之垢，乙之宝。</p><p>许多人会把你提供的东西看作垃圾。</p><p>但你不这么看，而且有成千上万像你一样的人。</p><p>为自己打造一款产品。</p><p>面向自己去做营销。</p><p>面向自己去写作。</p><p>吸引像你一样的人，因为他们正是你最能帮到的人。</p><h3 id="_2-为一种生理、个人、职业或社会问题创造解决方案。" tabindex="-1">2）为一种生理、个人、职业或社会问题创造解决方案。 <a class="header-anchor" href="#_2-为一种生理、个人、职业或社会问题创造解决方案。" aria-label="Permalink to &quot;2）为一种生理、个人、职业或社会问题创造解决方案。&quot;">​</a></h3><p>大多数企业之所以失败，是因为他们试图解决一个自己从未真正经历过的问题。</p><p>他们在脑海中编造出某个华丽的创业点子，然后用一个愚蠢的统计数字来为自己的失败开脱，比如“99%的创业公司都会失败”。</p><p>如果你把自己局限在一个狭窄的细分领域和一个你毫无经验的问题上，那基本没有出路。这就是我建议<a href="/letters/how-to-create-your-niche-of-one-become-nicheless">成为细分领域本身</a>的原因，因为你的企业只受限于你自我发展的能力。你的产品会随着你的成长而进化。</p><p>你围绕自己的名字建立受众。你用内容测试各种想法。你把那些最好的想法变成产品。你不断改进产品，或创造新的产品，直到成功为止。如果你自己就是这个企业,你几乎不可能真正失败,因为你完全掌控着自己的进步。</p><p>对初学者来说，最好的路径是那种门槛低、成本低的路径。</p><p>在互联网时代，这意味着数字产品和服务。</p><p>对于那些不懂编程的人来说，这意味着：</p><ul><li>课程</li><li>教练指导</li><li>模板</li><li>工作坊</li><li>直播活动</li><li>等等</li></ul><p>我最喜欢的一种教育产品形式，是把课程大纲和练习表或资源结合起来，你可以在 Notion 或 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 里搭建它。</p><p>你可以很快地做出这类产品。</p><p>你可以通过写内容并观察人们对其参与程度，来测试它们是否会受欢迎。</p><p>如果产品表现良好，你就可以从此享受高利润率——不管想享受多久都行，或者把它发展成另一个企业。</p><p>就像2 Hour Writer最终演变成了Kortex，因为作为一名写作者，Notion 对我来说已经不够用了。</p><p>但你该围绕什么来打造产品呢？</p><p>围绕你人生中已经解决过的一个问题。</p><p>你在生活的哪个领域已经达到了精通？</p><p>你热爱研究和学习的是什么？</p><p>你获得了哪些技能，帮助你过上了更好的生活，或找到了更好的职业？</p><p><em>围绕那个东西去打造一款产品。</em></p><p>把他们需要知道的一切,教给那些想达到与你相同目标的人。</p><p>如果你需要帮助，就去研究一下和你类似的人都在卖什么。</p><p>你能不能做出同样的东西，但做得更好？</p><h3 id="_3-建立、借用或购买一群拥有相同心理特征和相同问题的受众。" tabindex="-1">3）建立、借用或购买一群拥有相同心理特征和相同问题的受众。 <a class="header-anchor" href="#_3-建立、借用或购买一群拥有相同心理特征和相同问题的受众。" aria-label="Permalink to &quot;3）建立、借用或购买一群拥有相同心理特征和相同问题的受众。&quot;">​</a></h3><p>你已经拥有了人们想要的东西。现在你需要的是这个等式中“人”的那一部分。</p><p>大多数初学者都会陷入这样的陷阱——搭建网站、打磨产品、注册一家有限责任公司，做了这些之后，却始终没有顾上最重要的部分：</p><p>客户。</p><p>分发方式有三种。</p><p>建立的、借用的和购买的。</p><p>你可以在社交媒体和电子邮件列表这类东西上建立分发渠道。这是你自己拥有的东西，可以随时用来推广你的价值。这是其中杠杆效应最高的一种。</p><p>你可以通过与他人建立联系来借用分发渠道。比如以播客嘉宾的身份出现，让成千上万的人看到你；为拥有庞大订阅列表的人写客座通讯；在论坛网站或社区中发帖等等。</p><p>你可以用赞助和广告来购买分发渠道。播客赞助、newsletter 赞助、Google 广告、Facebook 广告、YouTube 广告等等。</p><p>在最理想的世界里，你会把这些全都做一遍。但你手上的时间有限，能雇人的钱也有限（如果你甚至想这么做的话）。</p><p>在我看来，对新手来说最好的选择是<em>打造</em>一个受众群体。</p><p>为什么？</p><p>因为这是免费开始的。</p><p>因为你必须学会如何抓住注意力和说服别人。你必须掌握那些<em>能让你借来的和买来的分发渠道取得成功</em>的技能。</p><p>当然，你还能把这些受众留在自己手里。他们是因为你本人而关注你的。你可以更真实、更有目的性。</p><p>如果你想学习如何做到这一点，去看我在 YouTube 上的<a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4&amp;si=WO--tXj7Ld284oii" target="_blank" rel="noreferrer">一人企业播放列表</a>，或者考虑购买 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>（写作正是你建立受众群体的方式）。</p><h3 id="_4-系统化地向那个受众群体推广并交付解决方案。" tabindex="-1">4）系统化地向那个受众群体推广并交付解决方案。 <a class="header-anchor" href="#_4-系统化地向那个受众群体推广并交付解决方案。" aria-label="Permalink to &quot;4）系统化地向那个受众群体推广并交付解决方案。&quot;">​</a></h3><p>人们会问我，为什么他们的创意工作没有赚到钱。</p><p>99% 的情况下，是他们停止了那些一开始让他们赚到钱的事情。</p><p>他们停止了推广。</p><p>他们停止了<em>努力</em>去获取客户。</p><p>他们没有建立一个可重复的每周系统，让自己能够测试和改进。</p><p>这里给出一个创作者商业模式的例子：</p><ul><li>每天都在同一条帖子下推广你的产品、服务、引流礼品或 newsletter。这可以是在那条帖子的评论区，也可以是在你的 story 里。</li><li>每周发一封 newsletter，并在其中推广一次你的产品或服务。</li><li>每周主动在私信里与 5-10 个人谈论你的产品。</li></ul><p>现在，你就有了从社交媒体流向你产品和邮件列表的流量。</p><p>你的邮件列表提供价值，同时推广你的产品。</p><p>一旦这一切设置好了，你要操心的就只剩下增长你的受众和邮件列表了。</p><p>当然，你也可以推出新产品，这样能带来销量的显著飙升，也给你的受众更多选择（因为一个产品只能满足受众中的某一部分人）。</p><p>我在<a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">《从零到一人企业百万美元》</a>里谈过这个话题。</p><h3 id="_5-迭代并坚持。" tabindex="-1">5）迭代并坚持。 <a class="header-anchor" href="#_5-迭代并坚持。" aria-label="Permalink to &quot;5）迭代并坚持。&quot;">​</a></h3><p>来回顾一下如何赚到你想要的任意多的钱：</p><ul><li>了解你自己的思维方式，这样你就能向和你相似的人营销。</li><li>把那些有益于你人生的技能、知识和兴趣，转化成一个教育产品。</li><li>把那个产品分发给你用内容和写作建立起来的受众群体。</li><li>建立一个每周系统，确保你的受众能看到你的产品。</li></ul><p>就是这样。</p><p>这就是你赚到任意多钱所需要的一切。</p><p>最后一块拼图，是迭代与坚持之间那种微妙的平衡。这正是大多数人失败的地方。</p><p>上面有 4 个要点。</p><p>每一个要点都会提供数据。</p><p>如果有什么不奏效，你就需要测试新的东西。</p><p>测试新的营销角度（利用你的个人经历，去讲述你的产品如何改变了你自己的生活），并观察反应。</p><p>测试你的产品在解决他人生活中的问题时到底有多有效。不断改进它，直到人们对它津津乐道、说个不停。</p><p>测试你用来建立受众群体的想法、内容和策略。如果你没有增长，那是因为你还没做到这一点。你的技能还不够高。</p><p>测试你每周该如何、何时、以多高的频率去推广你的产品，直到你实现你想要的销售额。</p><p>整个做生意这件事，并不会因为你选定了一个营销角度、一个产品、一个受众增长策略和一种推广方式就此停止。</p><p>只要你拥有所有正确的要素，并不断试验直到它们奏效，你就不可能失败。</p><p>感谢你阅读这封信。</p><p>希望它对你有所帮助。</p><p>—— Dan</p><hr><p><a href="/en/letters/the-truth-about-money-and-how-to-make-a-ton-of-it">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',239))])}const _=t(s,[["render",u]]);export{k as __pageData,_ as default};
